"use strict";
/* Language. Portuguese is the source text; English comes from EN below.
   _t('texto {0}', x) returns the text in the current language with {0},{1}… filled in.
   An EN value can be a function (for plurals and ordinals): it gets the same arguments.
   The language is read once at startup; changing it in Settings saves and reloads the game. */
const LANG=(()=>{
  try{const q=new URLSearchParams(location.search).get('lang');if(q==='en'||q==='pt')return q}catch(e){}
  try{return JSON.parse(localStorage.getItem('verity-settings')||'{}').lang==='en'?'en':'pt'}catch(e){return 'pt'}
})();
const DEC=LANG==='en'?'.':',';
const LOCALE=LANG==='en'?'en-US':'pt-BR';
const s_=n=>n===1?'':'s';
const ord=n=>{const v=n%100;return n+((v>=11&&v<=13)?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th'))};
