function _t(s,...a){
  let r=(LANG==='en'&&EN[s]!=null)?EN[s]:s;
  if(typeof r==='function')return r(...a);
  return a.length?r.replace(/\{(\d+)\}/g,(m,i)=>a[i]??''):r;
}
/* Static HTML: elements with data-t are translated as a whole (they mix text and tags); other text nodes and labels one by one. */
function translateDOM(root){
  if(LANG!=='en')return;
  const norm=s=>s.replace(/\s+/g,' ').trim();
  for(const e of root.querySelectorAll('[data-t]')){const k=norm(e.innerHTML);if(EN[k]!=null)e.innerHTML=EN[k]}
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(w.nextNode())nodes.push(w.currentNode);
  for(const n of nodes){const k=norm(n.nodeValue);if(k&&EN[k]!=null&&typeof EN[k]==='string'){const m=n.nodeValue.match(/^(\s*)[\s\S]*?(\s*)$/);n.nodeValue=m[1]+EN[k]+m[2]}}
  for(const a of ['placeholder','aria-label','title'])for(const e of root.querySelectorAll('['+a+']')){const k=e.getAttribute(a);if(EN[k]!=null)e.setAttribute(a,EN[k])}
}
if(LANG==='en'){document.documentElement.lang='en';document.title=EN['Cague um Verity'];translateDOM(document.body)}
